import{_ as e,o as r,c as o,ag as a}from"./chunks/framework.KxDd3USm.js";const c=JSON.parse('{"title":"12.2 命题逻辑、图论与数值误差 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"12-数学与多媒体/02-逻辑图论与数值误差.md","filePath":"12-数学与多媒体/02-逻辑图论与数值误差.md"}'),d={name:"12-数学与多媒体/02-逻辑图论与数值误差.md"};function n(l,t,s,i,g,h){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="_12-2-命题逻辑、图论与数值误差-★★★" tabindex="-1">12.2 命题逻辑、图论与数值误差 ★★★ <a class="header-anchor" href="#_12-2-命题逻辑、图论与数值误差-★★★" aria-label="Permalink to &quot;12.2 命题逻辑、图论与数值误差 ★★★&quot;">​</a></h1><h3 id="_3-1-基本联结词" tabindex="-1">3.1 基本联结词 <a class="header-anchor" href="#_3-1-基本联结词" aria-label="Permalink to &quot;3.1 基本联结词&quot;">​</a></h3><p>设 P、Q 为命题：</p><table tabindex="0"><thead><tr><th>形式</th><th>读法</th><th>何时为真</th></tr></thead><tbody><tr><td>¬P</td><td>非 P</td><td>P 为假</td></tr><tr><td>P∧Q</td><td>P 且 Q</td><td>两者都真</td></tr><tr><td>P∨Q</td><td>P 或 Q</td><td>至少一个真（通常是可兼或）</td></tr><tr><td>P→Q</td><td>若 P 则 Q</td><td><strong>只有 P 真、Q 假时为假</strong></td></tr><tr><td>P↔Q</td><td>P 当且仅当 Q</td><td>两者真假相同</td></tr></tbody></table><p>蕴含 <code>P→Q</code> 最容易反直觉。把它理解成承诺：“只要 P 发生，我保证 Q 发生。”只有 P 已发生而 Q 没发生，承诺才被打破。</p><table tabindex="0"><thead><tr><th style="text-align:right;">P</th><th style="text-align:right;">Q</th><th style="text-align:right;">P→Q</th></tr></thead><tbody><tr><td style="text-align:right;">真</td><td style="text-align:right;">真</td><td style="text-align:right;">真</td></tr><tr><td style="text-align:right;">真</td><td style="text-align:right;">假</td><td style="text-align:right;"><strong>假</strong></td></tr><tr><td style="text-align:right;">假</td><td style="text-align:right;">真</td><td style="text-align:right;">真</td></tr><tr><td style="text-align:right;">假</td><td style="text-align:right;">假</td><td style="text-align:right;">真</td></tr></tbody></table><p><code>P→Q</code> 的等价式：<strong>¬P∨Q</strong>；逆否命题：<strong>¬Q→¬P</strong>，与原命题等价。</p><p><strong>反例前置</strong>：原命题“若通过认证，则允许进入”不能推出“若允许进入，则通过认证”，后者是逆命题，未必成立；也不能只否定其中一边。与原命题等价的逆否命题是“若没有被允许进入，则没有通过认证”。</p><h3 id="_3-2-德摩根律" tabindex="-1">3.2 德摩根律 <a class="header-anchor" href="#_3-2-德摩根律" aria-label="Permalink to &quot;3.2 德摩根律&quot;">​</a></h3><p><strong>¬(P∧Q) = ¬P∨¬Q</strong><br><strong>¬(P∨Q) = ¬P∧¬Q</strong></p><p>口诀：<strong>括号外取反，里面每项取反，且与或互换</strong>。</p><p>例：“并非（系统安全且高效）”等价于“系统不安全或不高效”。</p><p><strong>反例</strong>：<code>¬(P∧Q)</code> 不能写成 <code>¬P∧¬Q</code>。只要两者中有一个不成立，“P 且 Q”就已被否定，所以中间应是“或”。</p><h3 id="_3-3-充分条件、必要条件与量词否定" tabindex="-1">3.3 充分条件、必要条件与量词否定 <a class="header-anchor" href="#_3-3-充分条件、必要条件与量词否定" aria-label="Permalink to &quot;3.3 充分条件、必要条件与量词否定&quot;">​</a></h3><p><code>P→Q</code> 中：P 是 Q 的<strong>充分条件</strong>，Q 是 P 的<strong>必要条件</strong>。</p><p>例：“是正方形 → 四边相等”。正方形足以保证四边相等，所以“是正方形”是充分条件；一个图形若是正方形，四边相等是必不可少的，所以“四边相等”是必要条件。</p><p>量词否定：</p><ul><li>“所有对象都满足 P”的否定：<strong>至少有一个对象不满足 P</strong>；</li><li>“至少有一个对象满足 P”的否定：<strong>所有对象都不满足 P</strong>。</li></ul><p><strong>反例</strong>：“所有测试都通过”的否定不是“所有测试都没通过”，而是“至少一个测试没通过”。</p><p><strong>应试动作</strong>：蕴含只背一个假情况“前真后假”；否定复合命题时用德摩根律；否定“所有”变“至少一个不”。</p><hr><h2 id="第四节-图论基础-点与边的三个送分公式-★★" tabindex="-1">第四节 图论基础：点与边的三个送分公式 ★★ <a class="header-anchor" href="#第四节-图论基础-点与边的三个送分公式-★★" aria-label="Permalink to &quot;第四节 图论基础：点与边的三个送分公式 ★★&quot;">​</a></h2><h3 id="_4-1-度数和公式-握手定理" tabindex="-1">4.1 度数和公式（握手定理） <a class="header-anchor" href="#_4-1-度数和公式-握手定理" aria-label="Permalink to &quot;4.1 度数和公式（握手定理）&quot;">​</a></h3><p>无向图中，每条边连接两个端点，因此每条边给总度数贡献 2：</p><p><strong>所有顶点度数之和 = 2|E|</strong></p><p>例：某无向图各顶点度数之和为 30，则边数 <code>|E|=30/2=15</code>。</p><p>推论：无向图中奇数度顶点的个数一定是偶数。</p><p>有向图中：</p><p><strong>所有顶点入度之和 = 所有顶点出度之和 = |E|</strong>。</p><h3 id="_4-2-完全图边数" tabindex="-1">4.2 完全图边数 <a class="header-anchor" href="#_4-2-完全图边数" aria-label="Permalink to &quot;4.2 完全图边数&quot;">​</a></h3><p>n 个顶点的无向完全图，每两个顶点之间都有一条边：</p><p><strong>|E|=C(n,2)=n(n−1)/2</strong></p><p>例：6 个结点两两直连，边数：</p><p><code>C(6,2)=(6×5)/(2×1)=15</code>。</p><p>n 个顶点的有向完全图若任意两个不同顶点之间两个方向的弧都存在，则弧数为 <strong>n(n−1)</strong>。</p><p><strong>反例（无向 vs 有向别混）</strong>：无向图同一对点只算 1 条边 → 要<strong>除以 2</strong>（<code>n(n−1)/2</code>）；有向图同一对点算两条相反方向的弧 → <strong>不除以 2</strong>（<code>n(n−1)</code>）。口诀：<strong>“无向折半，有向双份”</strong>。例：n=4 时无向完全图 <code>4×3/2=6</code> 条边，有向完全图 <code>4×3=12</code> 条弧。</p><h3 id="_4-3-树的边数" tabindex="-1">4.3 树的边数 <a class="header-anchor" href="#_4-3-树的边数" aria-label="Permalink to &quot;4.3 树的边数&quot;">​</a></h3><p>含 n 个顶点的无向树恰有：</p><p><strong>|E|=n−1</strong></p><p>树连通且无环。若一个连通无向图有 n 个顶点、n−1 条边，它就是树；树再加 1 条边必形成环，删掉任意一条已有边会不连通。</p><p>例：20 台设备用最少链路保持整体连通，至少需要 <code>20−1=19</code> 条链路。</p><p>本考点图论<strong>只有三个公式</strong>：无向完全图 <code>n(n−1)/2</code>、有向完全图 <code>n(n−1)</code>、树 <code>n−1</code>——考到就套，别往深里加料（大纲不考更复杂的图论）。</p><p><strong>应试动作</strong>：总度数除以 2 得边数；“两两相连”用组合数；“最少边保持连通”用 n−1。</p><hr><h2 id="第五节-数值误差-答案偏了多少-★★" tabindex="-1">第五节 数值误差：答案偏了多少 ★★ <a class="header-anchor" href="#第五节-数值误差-答案偏了多少-★★" aria-label="Permalink to &quot;第五节 数值误差：答案偏了多少 ★★&quot;">​</a></h2><p>设真值为 x，近似值为 x*：</p><ul><li><em><em>绝对误差 = |x−x</em>|</em>*；</li><li><em><em>相对误差 = |x−x</em>|/|x|</em>*（x≠0）；</li><li>百分相对误差 = 相对误差×100%。</li></ul><p>例：真值 20.00，近似值 19.80：</p><ul><li>绝对误差=<code>|20.00−19.80|=0.20</code>；</li><li>相对误差=<code>0.20/20.00=0.01</code>；</li><li>百分相对误差=<code>0.01×100%=1%</code>。</li></ul><p>反向检查：19.8 比 20 少 0.2，而 0.2 是 20 的百分之一，确为 1%。</p><h3 id="_5-1-截断与舍入" tabindex="-1">5.1 截断与舍入 <a class="header-anchor" href="#_5-1-截断与舍入" aria-label="Permalink to &quot;5.1 截断与舍入&quot;">​</a></h3><ul><li>截断：超过保留位数的部分直接丢弃；</li><li>四舍五入：看下一位决定末位是否加 1。</li></ul><p>将 3.146 保留两位小数：截断得 3.14，四舍五入得 3.15。真值按 3.146 计：</p><ul><li>截断绝对误差 0.006；</li><li>四舍五入绝对误差 0.004。</li></ul><p>本例中舍入误差更小，但不要背“任何计算中舍入都必然更准确”；连续运算还会传播和累积误差。</p><h3 id="_5-2-避免灾难性抵消" tabindex="-1">5.2 避免灾难性抵消 <a class="header-anchor" href="#_5-2-避免灾难性抵消" aria-label="Permalink to &quot;5.2 避免灾难性抵消&quot;">​</a></h3><p>两个非常接近的数相减，会把前面相同的有效数字消掉，使相对误差被放大，称为<strong>有效数字损失/灾难性抵消</strong>。数值计算题若给出等价公式，通常优先选避免“大数减大数”的形式。</p><p><strong>数值算例</strong>：算 <code>√(x+1) − √x</code>，当 x 较大（如 x=10⁶）时，<code>√(1000001)≈1000.0005</code>、<code>√(1000000)=1000</code>——两个都得存成约 1000 的接近大数，相减后只剩 0.0005，前面共享的&quot;1000&quot;有效位全被消掉，相对误差被大幅放大，这就是<strong>灾难性抵消</strong>。更稳的改法是分子有理化：<code>√(x+1) − √x = 1/(√(x+1)+√x) ≈ 1/2000.0005</code>——先把两个大数<strong>相加</strong>再取倒数，精度一下就保住了。题面若同时给出等价格式，优先选<strong>先相加</strong>（再取倒数 / 相减）的形态。</p><p><strong>应试动作</strong>：绝对误差有原量纲，相对误差无量纲；百分数别忘乘 100%。看到“保留若干位”先分清截断还是四舍五入。</p><hr>',60)])])}const P=e(d,[["render",n]]);export{c as __pageData,P as default};
